class Solution {
    Set<Integer> set = new HashSet<>();

    public boolean isHappy(int n) {
        var sum = 0;
        while (n != 0) {
            sum += (n % 10) * (n % 10);
            n /= 10;
        }

        if (sum == 1) {
            return true;
        }
        if (set.contains(sum)) {
            return false;
        }

        set.add(sum);

        return isHappy(sum);
    }
}

